function quotaOverrideForm(r={}){return `<div class="quota-override"><div class="form-grid">${select('대상 종류','overrideType',[['personal','멤버'],['team','팀']],r.type||'personal')}${field('멤버 아이디 또는 팀 번호','overrideId','required maxlength="100"',r.id||'')}${field('시작일','overrideFrom','type="date" required',r.from||'')}${field('종료일','overrideUntil','type="date" required',r.until||'')}${field('주간 한도 (시간)','overrideHours','type="number" min="0" max="40" step="0.5" required',r.hours??3)}</div>${button('이 한도 제거','remove-quota','small')}</div>`}
function specialPolicyForm(s){const p=s.specialPolicy||{enabled:false,from:'',until:'',allowedSessions:['드럼','키보드'],personalWeeklyHours:3,teamWeeklyHours:6};return `<section class="policy-section"><h2>기간별 특별 규칙</h2><label class="check-field"><input type="checkbox" name="specialEnabled" ${p.enabled?'checked':''}>특별 규칙 사용</label><p class="booking-hint">지정 기간의 새 예약에 적용합니다. 해당 주에 이미 예약한 시간도 주간 한도에 포함합니다. 0시간이면 새 예약이 불가합니다.</p><div class="form-grid">${field('시작일','specialFrom','type="date"',p.from)}${field('종료일','specialUntil','type="date"',p.until)}${field('개인 연습 허용 세션 (쉼표 구분, 빈칸은 전체)','specialSessions','maxlength="500"',p.allowedSessions.join(', '),true)}${field('개인 주간 한도','specialPersonal','type="number" min="0" max="40" step="0.5" required',p.personalWeeklyHours)}${field('팀 주간 한도','specialTeam','type="number" min="0" max="40" step="0.5" required',p.teamWeeklyHours)}</div></section><section class="policy-section"><h2>멤버·팀별 기간 한도</h2><p class="booking-hint">개별 한도 → 특별 규칙 → 기본 한도 순서로 적용합니다. 세션 제한은 개별 한도와 함께 적용됩니다. 팀 번호는 팀 목록에 표시됩니다.</p><div id="quota-overrides">${(s.quotaOverrides||[]).map(quotaOverrideForm).join('')}</div>${button('개별 한도 추가','add-quota','','plus')}</section>`}

function policyBanner(){const p=S.bookingData?.settings?.specialPolicy;return p?.enabled?`<details class="policy-banner"><summary>특별 운영 ${esc(p.from)} ~ ${esc(p.until)}</summary><p>개인 ${p.personalWeeklyHours}시간/주 · 팀 ${p.teamWeeklyHours}시간/주 · 개인 허용 세션: ${esc(p.allowedSessions.join(', ')||'전체')}. 대상별 별도 한도가 있으면 우선 적용됩니다.</p></details>`:''}

function feedbackModal(){showModal('문의 · 오류 제보',`<form id="feedback-form"><p class="booking-hint">어느 화면에서 무엇을 하다가 문제가 생겼는지 적어 주세요. 오류에 표시된 문의 번호가 있으면 함께 남겨 주세요. 비밀번호는 적지 마세요.</p><div class="field"><label for="feedback-message">내용</label><textarea id="feedback-message" name="message" required maxlength="2000"></textarea></div><div class="inline-error" role="alert"></div><div class="modal-actions">${button('취소','close-modal')}<button type="submit" class="btn primary">운영진에게 보내기</button></div></form>`)}
function activityDescription(e){
  const d=e.details||{};
  const booking=b=>[b.date,b.start&&b.end?`${b.start}–${b.end}`:'',b.teamName||b.memberName||(b.teamId?`팀 #${b.teamId}`:b.memberId||''),b.reservationName?`예약자: ${b.reservationName}`:'',b.bookingId||b.id?`예약 #${b.bookingId||b.id}`:''].filter(Boolean).join(' · ');
  if(e.action==='booking.cancel')return booking(d)||`예약 #${d.bookingId||'—'} 삭제 (과거 기록에는 상세 정보가 없을 수 있습니다.)`;
  if(e.action==='booking.cancel_series')return `반복 예약 ${d.count??d.bookingIds?.length??''}건 삭제\n`+(d.bookings?.map(booking).join('\n')||'과거 기록에는 날짜·시간 정보가 없을 수 있습니다.');
  if(e.action==='event.delete')return ['커스텀 일정 삭제',d.title,d.date,d.start&&d.end?`${d.start}–${d.end}`:'',d.eventId?`일정 #${d.eventId}`:''].filter(Boolean).join(' · ');
  return e.action==='feedback'?d.message:JSON.stringify(d,null,2);
}
function renderActivity(){const labels={'feedback':'부원 문의','booking.create':'예약 등록','booking.cancel':'예약 삭제','booking.cancel_series':'반복 예약 전체 삭제','event.delete_series':'반복 일정 전체 삭제','event.delete':'커스텀 일정 삭제','booking.transfer':'예약 명의 변경','team.create':'팀 추가','booking.rename':'예약자 이름 변경','import':'명단 등록','team.update':'팀 수정','profile.id_change':'아이디 변경','profile.update':'이름 수정(이전 기능)','settings.update':'예약 규칙 변경','password.reset':'비밀번호 재설정','password.change':'비밀번호 변경'};const filter=S.activityFilter||'all',filtered=filter==='cancellations';$('#main').innerHTML=pageHead('ACTIVITY','운영 기록·문의','선택한 종류의 최근 100건입니다. 삭제된 예약도 기록에서 확인할 수 있습니다.')+`<div class="modal-actions"><button class="btn ${filter==='all'?'primary':''}" data-action="activity-filter" data-filter="all" aria-pressed="${filter==='all'}">전체 기록</button><button class="btn ${filtered?'primary':''}" data-action="activity-filter" data-filter="cancellations" aria-pressed="${filtered}">예약 삭제 기록</button><button class="btn ${filter==='feedback'?'primary':''}" data-action="activity-filter" data-filter="feedback" aria-pressed="${filter==='feedback'}">문의 기록</button></div><div class="handbook">${S.entries.length?S.entries.map(e=>`<details class="panel activity-entry" ${filtered?'open':''}><summary>${esc(labels[e.action]||e.action)} · ${esc(e.actor_name||'운영 시스템')}<small>${esc(new Date(e.created_at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}))}</small></summary><pre>${esc(activityDescription(e))}</pre></details>`).join(''):'<p class="panel">해당 기록이 없습니다.</p>'}</div>`;icons()}

function clientPolicy(date,type,id,session=''){const settings=S.bookingData.settings,p=settings.specialPolicy,active=p?.enabled&&date>=p.from&&date<=p.until;let hours=type==='team'?settings.teamWeeklyHours:settings.personalWeeklyHours;if(active)hours=type==='team'?p.teamWeeklyHours:p.personalWeeklyHours;const match=(settings.quotaOverrides||[]).find(r=>r.type===type&&String(r.id)===String(id)&&date>=r.from&&date<=r.until);if(match)hours=match.hours;return {hours,allowed:!active||type!=='personal'||!p.allowedSessions.length||p.allowedSessions.some(x=>String(session).split(/[,/·\s]+/).includes(x))}}

function updateMarkdownPreview(){const preview=$('#markdown-preview');if(preview&&!preview.hidden)preview.innerHTML=window.renderMarkdown($('#body').value)}
async function importMarkdown(file){
  const form=$('#post-form');
  try{
    if(S.viewPost?.hasDocument)throw new Error('HTML로 가져온 문서는 새 Markdown 공지로 작성해 주세요.');
    if(!/\.(md|markdown)$/i.test(file.name)||file.size>120000)throw new Error('120KB 이하의 .md 또는 .markdown 파일을 선택해 주세요.');
    const text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer()).replace(/^\uFEFF/,'');
    if(text.length>30000)throw new Error('본문은 30,000자 이하로 입력해 주세요.');
    if(form!==$('#post-form'))return;
    $('#body').value=text;
    if(!form.title.value.trim())form.title.value=(text.match(/^#\s+(.+)$/m)?.[1]||file.name.replace(/\.(md|markdown)$/i,'')).slice(0,150);
    form.sourceUrl.value='';$('#markdown-preview').hidden=false;updateMarkdownPreview();$('#post-error').textContent='';
  }catch(e){if(form===$('#post-form'))$('#post-error').textContent=e instanceof TypeError?'UTF-8로 저장한 Markdown 파일을 선택해 주세요.':e.message}
}

let markdownLoading;
function loadMarkdown(){
  if(window.renderMarkdown)return Promise.resolve();
  if(!markdownLoading)markdownLoading=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/markdown.js';script.onload=()=>{if(window.renderMarkdown)resolve();else{markdownLoading=null;script.remove();reject(new Error('Markdown을 불러오지 못했습니다. 다시 시도해 주세요.'))}};script.onerror=()=>{markdownLoading=null;script.remove();reject(new Error('Markdown을 불러오지 못했습니다. 다시 시도해 주세요.'))};document.head.appendChild(script)});
  return markdownLoading;
}

function markdownArchiveModal(){S.markdownArchive=null;S.markdownFolder=null;showModal('이미지 포함 Markdown 가져오기',`<p>Markdown 문서와 이미지 폴더를 함께 선택하거나, 폴더를 압축한 ZIP을 올려 주세요. 이미지 경로와 폴더 구조를 유지해 주세요.</p><div class="field"><label for="markdown-archive-file">ZIP 파일 (최대 20MB)</label><input id="markdown-archive-file" type="file" accept=".zip"></div><div class="field"><label for="markdown-folder">또는 폴더 선택 (총 20MB 이하)</label><input id="markdown-folder" type="file" webkitdirectory multiple></div><p>PNG·JPG·GIF·WebP 이미지를 포함한 문서로 저장됩니다. 가져온 본문은 직접 편집할 수 없으므로 수정 시 다시 가져와 주세요. 글만 작성하려면 공지 작성을 사용하세요.</p><div id="markdown-page-selector"></div><div id="markdown-archive-error" role="alert"></div>`,`<div class="modal-actions">${button('취소','close-modal')}${button('가져오기','import-markdown-archive','primary')}</div>`,true)}
async function submitMarkdownArchive(el){el.disabled=true;try{
 let bytes;
 if(S.markdownArchive){if(S.markdownArchive.size>20*1024*1024)throw new Error('20MB 이하의 ZIP을 선택해 주세요.');bytes=await S.markdownArchive.arrayBuffer()}
 else if(S.markdownFolder?.length){if(S.markdownFolder.length>1000||S.markdownFolder.reduce((n,f)=>n+f.size,0)>20*1024*1024)throw new Error('폴더는 1,000개 파일·20MB 이하로 선택해 주세요.');const entries={};for(const f of S.markdownFolder)entries[f.webkitRelativePath]=new Uint8Array(await f.arrayBuffer());bytes=window.zipMarkdownFiles(entries).buffer}
 else throw new Error('ZIP 또는 Markdown과 이미지가 들어 있는 폴더를 선택해 주세요.');
 const result=await api('/markdown/import',{method:'POST',body:bytes,raw:true,headers:{'Content-Type':'application/octet-stream','X-Entry':encodeURIComponent($('#markdown-page')?.value||'')}});
 if(result.pages){$('#markdown-page-selector').innerHTML=select('가져올 문서','markdown-page',result.pages.map(p=>[p,p]),result.pages[0],true);return}
 closeModal();await navigate();readPost(result.id);toast('이미지가 포함된 Markdown 문서를 가져왔습니다.');
 }catch(e){$('#markdown-archive-error').textContent=e.message}finally{el.disabled=false}}

function expandImportedDocument(){
 const frame=document.querySelector('iframe.wiki-document:not(.notion-live)');if(!frame)return;
 let resize,removal;
 const cleanup=()=>{resize?.disconnect();removal?.disconnect()};
 frame.addEventListener('load',()=>{
  cleanup();const doc=frame.contentDocument;if(!doc?.body)return;
  const update=()=>{
   if(!frame.isConnected){cleanup();return}
   const style=frame.contentWindow.getComputedStyle(doc.body);
   const height=Math.ceil(doc.body.getBoundingClientRect().height+(parseFloat(style.marginTop)||0)+(parseFloat(style.marginBottom)||0));
   frame.style.height=Math.max(100,height)+'px';
  };
  doc.documentElement.style.overflowY='hidden';
  frame.style.minHeight='0';frame.style.maxHeight='none';
  resize=new ResizeObserver(update);resize.observe(doc.body);
  removal=new MutationObserver(()=>{if(!frame.isConnected)cleanup()});removal.observe(document.querySelector('#main'),{childList:true,subtree:true});
  doc.addEventListener('load',update,true);update();
 });
}

async function bookingOwnerModal(id){const b=S.bookings.find(b=>b.id===id);if(!b||!S.me.admin)return;const members=S.bookingData?.bookingMembers||(await api('/booking-options')).members;
 showModal('예약 명의 변경',`<form id="booking-owner-form" data-id="${id}">${b.type==='team'?select('변경할 팀','teamId',S.teams.map(t=>[t.id,t.name]),b.teamId,true):select('변경할 이용 멤버','memberId',members.map(m=>[m.id,m.name+' · '+m.id]),b.memberId,true)}<p>선택한 날짜 한 건의 실제 이용 명의를 변경합니다. 새 명의의 하루·주간 한도를 적용하며 최초 등록자와 표시 이름은 유지됩니다. 반복 예약은 이 날짜만 반복 묶음에서 분리됩니다.</p><div class="inline-error" role="alert"></div><div class="modal-actions">${button('취소','close-modal')}<button class="btn primary" type="submit">명의 변경</button></div></form>`)}

function calendarNow(){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).map(p=>[p.type,p.value]));return {date:`${parts.year}-${parts.month}-${parts.day}`,minute:Number(parts.hour)*60+Number(parts.minute)}}
function slotIsPast(date,time,clock=calendarNow()){return date<clock.date||(date===clock.date&&minutes(time)<=clock.minute)}
function refreshPastSlots(){const clock=calendarNow();document.querySelectorAll('.time-cell[data-date][data-time]').forEach(cell=>{const past=slotIsPast(cell.dataset.date,cell.dataset.time,clock),occupied=cell.classList.contains('occupied');cell.classList.toggle('past-slot',past);cell.disabled=(occupied&&cell.dataset.action==='pick-preview-slot')||(past&&!occupied);if(!occupied)cell.setAttribute('aria-label',`${cell.dataset.date} ${cell.dataset.time} ${past?'지난 시간 · 예약 불가':'예약 가능'}`)})}
